#pragma once

// Time zones (docs/architecture.md section 9.4): the IANA names with their POSIX TZ rules, and the
// local time under one rule, worked out here and not by the C library. The C library has one time
// zone for the whole firmware (TZ, set by platform to the zone of Home Assistant); a clock tile
// with a zone of its own (docs/ui/lvgl/lvgl-dashboard.md section 3) needs a second one, so the rule
// is evaluated in plain C++. Host tested against Python's zoneinfo.
//
// The table is timezones.inc, generated by tools/build_timezones.py from the IANA data: the rule
// of a zone is what it does after its last listed transition, right for today and the years
// ahead, not for dates in the past.

#include <cstddef>
#include <cstdint>
#include <ctime>
#include <string_view>

namespace hc::core {

// IANA names are at most about 30 characters ("America/Argentina/ComodRivadavia")
constexpr size_t kMaxZoneLength = 48;

// the POSIX rule of an IANA name ("Europe/Berlin" -> "CET-1CEST,M3.5.0,M10.5.0/3"), nullptr when
// the name is not in the table (names are case sensitive)
const char *time_zone_rule(std::string_view iana_name);

// the table, sorted by name: for lists
size_t time_zone_count();
std::string_view time_zone_name(size_t index);

// When daylight saving time starts or ends, as POSIX writes it: `Mm.w.d` (month, week 1 to 5 where
// 5 is the last, weekday 0 = Sunday), `Jn` (day 1 to 365, February 29 never counted) or `n` (day
// 0 to 365, February 29 counted), at `seconds` of the local time in force before the transition
// (may be negative or beyond 24 h: "M3.5.0/-1", "M9.1.6/24").
struct TzTransition {
    enum class Kind : uint8_t { MonthWeekDay, Julian1, Julian0 };
    Kind kind = Kind::MonthWeekDay;
    uint8_t month = 0;
    uint8_t week = 0;
    uint8_t weekday = 0;
    uint16_t day = 0;
    int32_t seconds = 7200;
};

// A parsed rule. Offsets are seconds east of UTC (the POSIX string has them west: "CET-1" is +3600).
struct TzRule {
    int32_t std_offset = 0;
    int32_t dst_offset = 0;
    bool has_dst = false;
    TzTransition start; // daylight saving time begins
    TzTransition end;   // and ends
};

// "CET-1CEST,M3.5.0,M10.5.0/3", "<-03>3<-02>,M3.2.0,M11.1.0", "IST-5:30", "<+00>0". False when
// the text is not a rule (`out` is unchanged then). A rule with a DST name needs both transitions.
bool parse_tz_rule(std::string_view text, TzRule &out);

// The civil time of `epoch` (seconds since 1970 UTC) under `rule`: year, month, day, hour, minute,
// second, weekday, day of the year and tm_isdst of `out`. Nothing else of `out` is set.
void local_time(int64_t epoch, const TzRule &rule, std::tm &out);

} // namespace hc::core
